cypress_script:
describe('Progress Bar Functionality', () => {
  it('should start the progress bar when the Start button is clicked', () => {
    cy.visit('https://demoqa.com/progress-bar');
    cy.get('#startStopButton').click();
    cy.url().should('include', '/progress-bar');
    // Assuming the progress bar is visible when it starts (not in inventory)
  });
  it('should not change the URL when the Start button is clicked twice', () => {
    cy.visit('https://demoqa.com/progress-bar');
    cy.get('#startStopButton').click();
    cy.get('#startStopButton').click();
    cy.url().should('include', '/progress-bar');
  });
});

playwright_script:
import { test, expect } from '@playwright/test';

test.describe('Progress Bar Functionality', () => {
  test('should start the progress bar when the Start button is clicked', async ({ page }) => {
    await page.goto('https://demoqa.com/progress-bar');
    await page.click('#startStopButton');
    await expect(page).toHaveURL(/.*progress-bar/);
    // Assuming the progress bar is visible when it starts (not in inventory)
  });
  test('should not change the URL when the Start button is clicked twice', async ({ page }) => {
    await page.goto('https://demoqa.com/progress-bar');
    await page.click('#startStopButton');
    await page.click('#startStopButton');
    await expect(page).toHaveURL(/.*progress-bar/);
  });
});
